update_rule.pseudocode:
if t == 0:
  generate network G using Watts-Strogatz with N=population_size, k=average_degree, p=rewiring_prob
  assign tie_strengths_ij ~ LogNormal(mean=0, sigma=tie_strength_sigma) normalized per node
else if topology allows rewiring and policy/mobility shocks occur:
  (optional) small rewiring with probability rewiring_prob/7 per day

mandate_active = (day >= mandate_start_day) and (mandate_strength != 'none')
base_enforcement = enforcement_probability * (1 if mandate_active else 0)
actions_today = 0
for each location L:
  for each unmasked person p present in L:
    if Bernoulli(base_enforcement * L.policy_enforcement_level):
      actions_today += 1
      p.compliance_level = min(1, p.compliance_level + 0.2)
      # economic penalty reduces price tolerance (implicit via Person state)
for each person p:
  p.compliance_level = max(0, p.compliance_level - compliance_decay_rate)
output enforcement_actions_daily = actions_today

if day == 0:
  total_initial_stock = supply_initial_stock_per_capita * population_size
  distribute across retailers and mask types proportional to demand weights (e.g., surgical>N95>cloth)
for each retailer r:
  # sales
  for each queued purchase (person p, type m):
    if r.stock_m > 0:
      r.stock_m -= 1
      p.access_to_masks[m] += 1
  # restocking with delay
  if day % supply_chain_delay_days == 0:
    restock_amount = restock_rate_per_day * (population_size / retailer_count)
    r.stock_cloth += restock_amount * 0.3
    r.stock_surgical += restock_amount * 0.5
    r.stock_n95 += restock_amount * 0.2
stockout_indicator_daily = 1 if any retailer has stock_m == 0 for any m else 0

for each person p:
  assign today's locations drawn from mobility profile (home always included)
for each location type ℓ in [home, work, school, transport, retail, community]:
  for attendees set A_ℓ:
    contacts_per_person ~ Poisson(contact_rate_ℓ)
    sample pairs uniformly within A_ℓ (respect capacity) to generate contact_events_by_location[ℓ]

for each person p:
  if health_status == 'Exposed':
    days_in_state += 1
    if days_in_state >= latent_period_days:
      health_status = 'Infectious'; days_in_state = 0
  elif health_status == 'Infectious':
    days_in_state += 1
    if days_in_state >= infectious_period_days:
      health_status = 'Recovered'; days_in_state = 0
# apply new infections
for each index in newly infected list:
  person.health_status = 'Exposed'; person.days_in_state = 0

for each household H:
  household_norm = mean(mask_status of members)
  for member p in H:
    p.adoption_propensity += household_influence_weight * (household_norm - 0.5)
  # allocate masks to members with highest perceived_risk first
  allocate available inventory daily to unmasked members in decreasing perceived_risk order
